<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            line-height: 1.6;
            color: #333;
            max-width: 600px;
            margin: 20px auto;
            padding: 0 20px;
            background-color: #f4f7f6;
        }

        h1, h2 { color: #2c3e50; }

        .card {
            background: #fff;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.1);
            margin-bottom: 20px;
        }

        .form-group { margin-bottom: 15px; }

        label {
            display: block;
            font-weight: bold;
            margin-bottom: 5px;
            font-size: 0.9rem;
        }

        input, select, textarea {
            width: 100%;
            padding: 8px;
            border: 1px solid #ccc;
            border-radius: 4px;
            box-sizing: border-box;
            font-size: 1rem;
        }

        #form-error {
            color: #d9534f;
            font-weight: bold;
            margin-bottom: 15px;
            min-height: 1.2em;
        }

        button {
            cursor: pointer;
            border: none;
            border-radius: 4px;
            padding: 10px 15px;
            font-weight: bold;
            transition: opacity 0.2s;
        }

        #add-expense {
            background-width: 100%;
            background-color: #28a745;
            color: white;
            width: 100%;
            font-size: 1rem;
        }

        button:hover { opacity: 0.9; }

        #add-expense:active { transform: translateY(1px); }

        .filters {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }
        .filters .form-group:first-child { grid-column: span 2; }

        .summary-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
            gap: 10px;
            margin-top: 10px;
        }

        .summary-item {
            background: #e9ecef;
            padding: 10px;
            border-radius: 4px;
            text-align: center;
            font-size: 0.85rem;
        }

        .total-display {
            font-size: 1.4rem;
            font-weight: bold;
            color: #2c3rub;
            margin-bottom: 15px;
            padding-top: 10px;
            border-top: 2px solid #eee;
        }

        .expense-list { margin-top: 20px; }

        .expense {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 12px;
            border-bottom: 1px solid #eee;
            background: #fff;
            margin-bottom: 5px;
            border-radius: 4px;
        }

        .expense-info { flex-grow: 1; }
        .exp-details { font-size: 0.8rem; color: #666; }
        .exp-amount { font-weight: bold; margin-right: 15px; }
        .exp-cat { 
            display: inline-block; 
            background: #eee; 
            padding: 2px 6px; 
            border-radius: 4px; 
            font-size: 0.75rem; 
            margin-right: 8px;
        }

        .exp-del {
            background-color: #dc3545;
            color: white;
            padding: 5px 10px;
            font-size: 0.8rem;
        }

        .note-text {
            display: block;
            font-style: italic;
            font-size: 0.85rem;
            color: #777;
        }
    </style>
</head>
<body>

    <div class="card">
        <h1>Add Expense</h1>
        <div id="form-error"></div>
        <form id="expense-form">
            <div class="form-group">
                <label for="amount">Amount ($)</label>
                <input type="number" id="amount" step="0.01" placeholder="0.00">
            </div>
            <div class="form-group">
                <label for="category">Category</label>
                <select id="category">
                    <option value="groceries">Groceries</option>
                    <option value="transport">Transport</option>
                    <option value="bills">Bills</option>
                    <option value="fun">Fun</option>
                </select>
            </div>
            <div class="form-group">
                <label for="date">Date</label>
                <input type="date" id="date">
            </div>
            <div class="form-group">
                <label for="note">Note (Optional)</label>
                <textarea id="note" rows="2"></textarea>
            </div>
            <button type="submit" id="add-expense">Add Expense</button>
        </form>
    </div>

    <div class="card">
        <h2>Filters</h2>
        <div class="filters">
            <div class="form-group" style="grid-column: span 2;">
                <label for="filter-category">Filter Category</label>
                <select id="filter-category">
                    <option value="all">All Categories</option>
                    <option value="groceries">Groceries</option>
                    <option value="transport">Transport</option>
                    <option value="bills">Bills</option>
                    <option value="fun">Fun</option>
                </select>
            </div>
            <div class="form-group">
                <label for="filter-from">From Date</label>
                <input type="date" id="filter-from">
            </div>
            <div class="far-group">
                <label for="filter-to">To Date</label>
                <input type="date" id="filter-to">
            </div>
        </div>

        <div class="total-display">
            Total: $<span id="total">0.00</span>
        </div>

        <div class="summary-grid">
            <div class="summary-item">
                Groceries: <br><span class="cat-total" data-cat="groceries">$0.00</span>
            </div>
            <div class="summary-item">
                Transport: <br><span class="cat-total" data-cat="transport">$0.00</span>
            </div>
            <div class="summary-item">
                Bills: <br><span class="cat-total" data-cat="bills">$0.00</span>
            </div>
            <div class="summary-item">
                Fun: <br><span class="cat-total" data-cat="fun">$0.00</span>
            </div>
        </div>
    </div>

    <div id="expense-list" class="expense-list">
        <!-- Expenses injected here -->
    </div>

    <script>
        // State management
        let expenses = JSON.parse(localStorage.getItem('expenses')) || [];

        const form = document.getElementById('expense-none'); // Not used, using ID below
        const expenseForm = document.getElementById('expense-form');
        const amountInput = document.getElementById('amount');
        const categoryInput = document.getElementById('category');
        const dateInput = document.getElementById('date');
        const noteInput = document.getElementById('note');
        const errorDisplay = document.getElementById('form-error');
        const addBtn = document.getElementById('add-expense');

        const filterCat = document.getElementById('filter-category');
        const filterFrom = document.getElementById('filter-from');
        const filterTo = document.getElementById('filter-to');

        const listContainer = document.getElementById('expense-list');
        const totalDisplay = document.getElementById('total');
        const catTotals = document.querySelectorAll('.cat-total');

        // Initialization
        window.addEventListener('DOMContentLoaded', render);

        // Form Submission
        expenseForm.addEventListener('submit', (e) => {
            e.preventDefault();
            errorDisplay.textContent = '';

            const amount = parseFloat(amountInput.value);
            const category = categoryInput.value;
            const date = dateInput.value;
            const note = noteInput.value.trim();

            // Validation
            if (isNaN(amount) || amount <= 0) {
                errorDisplay.textContent = 'Please enter a valid positive amount.';
                return;
            }
            if (!date) {
                errorDisplay.textContent = 'Please select a date.';
                return;
            }

            // Create object
            const newExpense = {
                id: Date.now(),
                amount,
                category,
                date,
                note
            };

            expenses.push(newExpense);
            saveAndRender();

            // Reset form
            amountInput.value = '';
            dateInput.value = '';
            noteInput.value = '';
            categoryInput.selectedIndex = 0;
        });

        // Delete Functionality
        function deleteExpense(id) {
            expenses = expenses.filter(exp => exp.id !== id);
            saveAndRender();
        }

        // Filters
        [filterCat, filterFrom, filterTo].forEach(el => {
            el.addEventListener('change', render);
        });

        function saveAndRender() {
            localStorage.setItem('expenses', JSON.stringify(expenses));
            render();
        }

        function render() {
            const selectedCat = filterCat.value;
            const fromDate = filterFrom.value ? new Date(filterFrom.value) : null;
            const toDate = filterTo.value ? new Date(filterTo.value) : null;

            // Filter the list
            const filteredExpenses = expenses.filter(exp => {
                const matchCat = (selectedCat === 'all' || exp.category === selectedCat);
                const expDate = new Date(exp.date);
                const matchFrom = !fromDate || expDate >= fromDate;
                const matchTo = !toDate || expDate <= toDate;
                return matchCat && matchFrom && matchTo;
            });

            // Sort: Newest date first
            filteredExpenses.sort((a, b) => new Date(b.date) - new Date(a.date));

            // Clear UI
            listContainer.innerHTML = '';
            let grandTotal = 0;
            const catTotalsMap = { groceries: 0, transport: 0, bills: 0, fun: 0 };

            // Build List
            filteredExpenses.forEach(exp => {
                grandTotal += exp.amount;
                if (catTotalsMap.hasOwnProperty(exp.category)) {
                    catTotalsMap[exp.category] += exp.amount;
                }

                const row = document.createElement('div');
                row.className = 'expense';
                row.innerHTML = `
                    <div class="expense-info">
                        <div>
                            <span class="exp-cat">${exp.category}</span>
                            <span class="exp-details">${exp.date}</span>
                        </div>
                        ${exp.note ? `<span class="note-text">${exp.note}</span>` : ''}
                    </div>
                    <div class="exp-amount">$${exp.amount.toFixed(2)}</div>
                    <button class="exp-del" onclick="deleteExpense(${exp.id})">Delete</button>
                `;
                listContainer.appendChild(row);
            });

            // Update Grand Total
            totalDisplay.textContent = grandTotal.toFixed(2);

            // Update Category Totals
            catTotals.forEach(el => {
                const catName = el.getAttribute('data-cat');
                const val = catTotalsMap[catName] || 0;
                el.textContent = `$${val.toFixed(2)}`;
            });

            if (filteredExpenses.length === 0) {
                listContainer.innerHTML = '<p style="text-align:center; color:#999;">No expenses found.</p>';
            }
        }
    </script>
</body>
</html>
